ALTER TABLE "unmatched_pos_documents" ADD CONSTRAINT "unmatched_pos_documents_suggestion_fields_together_check" CHECK (("unmatched_pos_documents"."suggested_client_id" IS NULL AND "unmatched_pos_documents"."suggestion_method" IS NULL AND "unmatched_pos_documents"."suggested_at" IS NULL) OR ("unmatched_pos_documents"."suggested_client_id" IS NOT NULL AND "unmatched_pos_documents"."suggestion_method" IS NOT NULL AND "unmatched_pos_documents"."suggested_at" IS NOT NULL));